<include file="Public:header"/><style>    .station{width: 150px; height: 40px; float: left;}</style><form id="myform" method="post" action="{pigcms{:U('National_phone/add')}" >	<input type="hidden" name="id" value="{pigcms{$national_phone.id}"/>    <table cellpadding="0" cellspacing="0" class="frame_form" width="100%">		<tr>            <td width="80">国家/地区名称</td>            <td><input type="text" class="input fl" name="national" value="{pigcms{$national_phone.national}" size="30" placeholder="国家/地区名称" validate="required:true" tips=""/></td>        </tr>        <tr>            <td width="80">区号代码</td>            <td><input type="text" class="input fl" name="code" id="code" size="30" placeholder="" validate="maxlength:20,required:true" tips="" value="{pigcms{$national_phone.code}"/></td>        </tr>		<tr>            <td width="80">号码长度</td>            <td><input type="text" class="input fl" name="length" id="length" size="30" placeholder="" tips="非必填项。若号码存在长度不一致，不要填写此项。填写后系统会尽量的按此格式去匹配，表单匹配不断完善，可能会存在没有匹配处。" value="{pigcms{$national_phone.length|default=''}"/></td>        </tr>		<tr>            <td width="80">匹配规则</td>            <td><input type="text" class="input fl" name="match" id="match" size="30" placeholder="" tips="非必填项，正则表达式，判断手机号格式是否正确。非技术人员不要填写。填写后系统会尽量的按此格式去匹配，表单匹配不断完善，可能会存在没有匹配处。" value="{pigcms{$national_phone.match}"/></td>        </tr>		<tr>            <td width="80">排序</td>            <td><input type="text" class="input fl" name="sort" value="{pigcms{$national_phone.sort|floatval}" size="30" placeholder="排序" validate="maxlength:6,required:true" tips=""/></td>        </tr>        <tr>            <td width="80">状态</td>            <td class="radio_box">				<span class="cb-enable">					<label class="cb-enable <if condition="$national_phone.status eq 1">selected</if>">                        <span>启用</span>                        <input type="radio" name="status" value="1" <if condition="$national_phone.status eq 1"> checked="checked" </if> />					</label>				</span>				<span class="cb-disable">					<label class="cb-disable <if condition="$national_phone.status eq 0">selected</if>">                        <span>禁用</span>                        <input type="radio" name="status" value="0" <if condition="$national_phone.status eq 0"> checked="checked" </if> />					</label>				</span>            </td>        </tr>    </table>    <div class="btn hidden">        <input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />        <input type="reset" value="取消" class="button" />    </div></form><include file="Public:footer"/>